tool_input.command:
$f = "D:\repository\skills\dsh\AGENTS.md"
$raw = [System.IO.File]::ReadAllText($f)
$NL = "`r`n"; if(-not $raw.Contains($NL)){ $NL = "`n" }

# ---- 4 new rule bullets ----
$a1 = '- **小文件禁整写（2026-11-14 复盘）**：≤40 行的小文件禁止整篇 `write`，必须先 `read` 全文再逐段 `edit`；JS 文件每次 `edit` 后立即 `node --check`（非 JS 文件用对应语法检查或跳过，不硬套 `node --check`）。本规则与上条「已有文件一律 edit」同源，合并执行。'
$a2 = '- **脱敏视图不可作 edit 依据（2026-11-14 复盘）**：工具对含 token 赋值或 `===` 比较等敏感行会脱敏显示（显示为掩码），此时不得据脱敏视图猜 `old_string`；须先 `grep -n` 取行号 → `read offset/limit` 局部读真实内容再 `edit`。反例：context-store.mjs 的 token 赋值行被掩码，据掩码猜 `old_string` 导致 FS_EDIT_NOT_FOUND，随后整篇 write 靠记忆补语义引发回归。'
$a3 = '- **测试不得反向扩展生产 API（2026-11-14 复盘）**：白盒断言不得因测试需要而新增生产导出；若某个导出仅测试用（如 cost-meter 的 inspectSize），改为用既有出口（inspect/apply 返回值）做**行为断言**（如 LRU：hot 存活 / 最早淘汰 / 最新在），**不承诺精确内部计数（size 等）**。'
$a4 = '- **一次问清（2026-11-14 复盘）**：计划确认轮须把可预见待定项（上限取值、是否实施、严谨度补充、提交方式）合并为**一次** `ask_user_question`（带默认选项），不得拆成多轮；已有 ask-guard 拦截二次 ask，此处为「未覆盖项并入首次提问」的正面清单。反例：turn3 三次人工等待、其中一次 ask 等待约 22 分钟。'

# ---- anchors (must each occur exactly once) ----
$anchors = @(
  @{ name='A1'; anchor='（复盘实例：2 次 edit 触发 3 次全文 instructions 重发；step 28 一次 5.8k output 重写 5 节）。一次大改拆成 2–3 次中等 edit，避免单步过大。'; add=@($a1,$a3) },
  @{ name='A2'; anchor='（反例：483 行组件整读两遍只改 3 行 CSS）。'; add=@($a2) },
  @{ name='A4'; anchor='- 要用户选择时只用 `ask_user_question`，禁止在正文末尾提问。已回答且范围未变的不重复问。'; add=@($a4) }
)

# pre-check
$fail = $false
foreach($it in $anchors){
  $c = ([regex]::Matches($raw, [regex]::Escape($it.anchor))).Count
  if($c -ne 1){ Write-Output ("ANCHOR_FAIL {0}: count={1}" -f $it.name,$c); $fail=$true }
}
if($fail){ Write-Output "ABORT: anchor not unique, no change made"; exit 1 }

# apply via literal replace (anchor -> anchor + NL + new bullets)
foreach($it in $anchors){
  $repl = $it.anchor
  foreach($b in $it.add){ $repl += $NL + $b }
  $raw = $raw.Replace($it.anchor, $repl)
}
[System.IO.File]::WriteAllText($f, $raw)
Write-Output ("OK written, newLen=" + $raw.Length + " garbled=" + $raw.Contains([char]0xFFFD))
